  /** API Details: Describes details about a typical API (Application Programming Interface) call. (optional; profiles cloud) */
  readonly api?: OcsfApi;
  /** Assignee: The details of the user assigned to an Incident. (optional; profiles incident) */
  readonly assignee?: OcsfUser;
  /** Assignee Group: The details of the group assigned to an Incident. (optional; profiles incident) */
  readonly assignee_group?: OcsfGroup;
  /** MITRE ATT&CK® and ATLAS™ Details: An array of MITRE ATT&CK® objects describing identified tactics, techniques & sub-techniques. The objects are compatible with MITRE ATLAS™ tactics, techniques & sub-techniques. (optional; profiles security_control) */
